CREATE DATABASE IF NOT EXISTS perpustakaan_unpam CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE perpustakaan_unpam;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('petugas','anggota') NOT NULL DEFAULT 'anggota',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE members(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,member_number VARCHAR(40) NOT NULL UNIQUE,member_type ENUM('mahasiswa','dosen') NOT NULL,phone VARCHAR(30),address TEXT,active TINYINT(1) NOT NULL DEFAULT 1,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE books(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,isbn VARCHAR(30) UNIQUE,title VARCHAR(180) NOT NULL,author VARCHAR(150) NOT NULL,publisher VARCHAR(150),publication_year SMALLINT UNSIGNED,stock INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE loans(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,member_id BIGINT UNSIGNED NOT NULL,book_id BIGINT UNSIGNED NOT NULL,loaned_at DATE NOT NULL,returned_at DATE,status ENUM('dipinjam','dikembalikan') NOT NULL DEFAULT 'dipinjam',processed_by BIGINT UNSIGNED NOT NULL,FOREIGN KEY(member_id) REFERENCES members(id),FOREIGN KEY(book_id) REFERENCES books(id),FOREIGN KEY(processed_by) REFERENCES users(id)) ENGINE=InnoDB;
